def levenshtein(a, b):
    # standard DP
    if a == b:
        return 0
    la, lb = len(a), len(b)
    if la == 0:
        return lb
    if lb == 0:
        return la
    prev = list(range(lb+1))
    for i in range(1, la+1):
        cur = [i] + [0]*lb
        ca = a[i-1]
        for j in range(1, lb+1):
            cost = 0 if ca == b[j-1] else 1
            cur[j] = min(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
        prev = cur
    return prev[lb]

def suggest_long_flag(cmd, unknown):
    # unknown is like '--foo'
    specs = OPTION_SPECS.get(cmd, {})
    candidates = list(specs.keys())
    best = None
    best_dist = None
    for c in candidates:
        d = levenshtein(unknown, c)
        if best_dist is None or d < best_dist:
            best_dist = d
            best = c
    if best_dist is not None and best_dist <= 2:
        return best
    return None

class ArgError(Exception):
    pass

def parse_cmd_args(cmd, argv):
    """
    Parse argv (list of str) for cmd.
    Returns (opts dict long_name->value, positionals list, help_flag bool)
    Raises ArgError with message bytes to be printed to stderr (including usage)
    Message should already include trailing \n and usage.
    """
    specs = OPTION_SPECS[cmd]
    # Build short->long map
    short_to_long = {}
    for long, (short, takes) in specs.items():
        if short is not None:
            short_to_long[short] = (long, takes)
    opts = {}
    # defaults? We'll set defaults later per command; here just collect provided
    positionals = []
    help_flag = False
    i = 0
    n = len(argv)
    end_options = False
    while i < n:
        tok = argv[i]
        if end_options:
            positionals.append(tok)
            i += 1
            continue
        if tok == '--':
            end_options = True
            i += 1
            continue
        if tok.startswith('--'):
            # long flag
            if '=' in tok:
                flag, val = tok.split('=', 1)
                # flag is --xxx
                if flag not in specs:
                    # unknown
                    sugg = suggest_long_flag(cmd, flag)
                    if sugg:
                        msg = f"Unknown flag: '{flag}'. Did you mean '{sugg}'?\n\n".encode() + SHORT_USAGES[cmd]
                    else:
                        msg = f"Unknown flag: '{flag}'\n\n".encode() + SHORT_USAGES[cmd]
                    raise ArgError(msg)
                short, takes = specs[flag]
                if not takes:
                    msg = f"Flag '{flag}' cannot have an argument, but found '{val}'.\n\n".encode() + SHORT_USAGES[cmd]
                    raise ArgError(msg)
                # takes arg, val is value (may be empty)
                opts[flag] = val
                if flag == '--help':
                    help_flag = True
                i += 1
                continue
            else:
                flag = tok
                if flag not in specs:
                    sugg = suggest_long_flag(cmd, flag)
                    if sugg:
                        msg = f"Unknown flag: '{flag}'. Did you mean '{sugg}'?\n\n".encode() + SHORT_USAGES[cmd]
                    else:
                        msg = f"Unknown flag: '{flag}'\n\n".encode() + SHORT_USAGES[cmd]
                    raise ArgError(msg)
                short, takes = specs[flag]
                if takes:
                    # need next token
                    if i+1 >= n:
                        msg = f"Expected argument for flag '{flag}' but reached end of arguments.\n\n".encode() + SHORT_USAGES[cmd]
                        raise ArgError(msg)
                    val = argv[i+1]
                    opts[flag] = val
                    i += 2
                    continue
                else:
                    opts[flag] = True
                    if flag == '--help':
                        help_flag = True
                    i += 1
                    continue
        elif tok.startswith('-') and len(tok) > 1:
            # short flags, possibly bundled or with attached value
            # tok is like '-x', '-xyz', '-xVALUE'
            # Process chars after '-'
            j = 1
            consumed_next = False
            while j < len(tok):
                ch = tok[j]
                if ch not in short_to_long:
                    msg = f"Unknown flag: '-{ch}'\n\n".encode() + SHORT_USAGES[cmd]
                    raise ArgError(msg)
                long, takes = short_to_long[ch]
                if takes:
                    # rest of tok after ch is value if any, else next token
                    rest = tok[j+1:]
                    if rest != '':
                        # attached value (including leading '='? e.g., -o=OUT -> rest '=OUT')
                        opts[long] = rest
                    else:
                        if i+1 >= n:
                            msg = f"Expected argument for flag '{long}' but reached end of arguments.\n\n".encode() + SHORT_USAGES[cmd]
                            raise ArgError(msg)
                        opts[long] = argv[i+1]
                        consumed_next = True
                    # takes arg consumes rest, break out of bundled loop
                    break
                else:
                    opts[long] = True
                    if long == '--help':
                        help_flag = True
                    j += 1
                    continue
            if consumed_next:
                i += 2
            else:
                i += 1
            continue
        else:
            # positional (including '-' alone)
            positionals.append(tok)
            i += 1
            continue
    return opts, positionals, help_flag

def check_usage(cmd, opts, positionals, help_flag):
    """
    Check if positionals match usage. If not, raise ArgError Invalid arguments.
    Also handle second usage (--help) for commands that have it.
    Returns nothing if ok.
    If help_flag and valid, caller should show help (but we don't decide here).
    Logic:
    - For each cmd, define valid positional counts for main usage.
    - If matches main usage, return (valid).
    - Else if help_flag and matches --help usage (i.e., only --help flag, no other opts besides help, and no positionals? But tests show select --help foo (with positional) matches main usage, not second. So second usage only when main invalid but args are exactly --help with no other flags/positionals? Actually select -h (no positionals, only help) matches second, so valid. What about select --help with extra positionals that make main invalid? e.g., select --help a b c (3 positionals, main allows 1-2, invalid, second requires 0 positionals, also invalid, so overall invalid. But our earlier test join --help a b c d (4 positionals, main requires 4, valid, so matches main, help. Good.
    - For cat, special handling.
    """
    # Define main usage positional requirements
    # Returns (min, max) or special
    if cmd == 'cat':
        # Must have at least 1 positional (mode), mode must be rows/columns
        # If positionals == [] -> invalid (unless help second usage? cat --help with no positionals matches second)
        # If help_flag and positionals == [] and only help opt -> matches second -> valid
        # Else if positionals >=1 and positionals[0] in ('rows','columns') -> valid (any number of inputs after)
        # Else invalid
        # Also need to check: cat --help with extra flags? e.g., cat --help --pad? That would be positionals [] but opts has --pad + --help. Does it match second? Second is exactly 'cat --help' with no other flags. So with extra flag, invalid. Our earlier test didn't cover, but assume.
        # Similarly cat rows --help (positionals ['rows'], help) -> matches main (mode rows) -> valid -> help.
        # cat badmode --help (positionals ['badmode'], help) -> main invalid (bad mode), second invalid (has positional), so invalid.
        if len(positionals) == 0:
            # Check if matches second usage: only help flag, no other opts
            # opts may contain --help plus maybe others? If only --help, valid second.
            other_opts = {k:v for k,v in opts.items() if k != '--help'}
            if help_flag and len(other_opts) == 0:
                return
            else:
                # No mode, invalid (even with help? e.g., cat --pad --help with no mode? positionals [], opts pad+help -> invalid, since second requires no other flags, main requires mode)
                raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
        else:
            mode = positionals[0]
            if mode in ('rows', 'columns'):
                return
            else:
                raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
    elif cmd in ('count','fixlengths','flatten','fmt','frequency','input','reverse','slice','sort','stats','table'):
        # [<input>] : 0 or 1 positional
        if len(positionals) <= 1:
            return
        else:
            raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
    elif cmd == 'headers':
        # [<input>...] : 0+
        return
    elif cmd == 'index':
        # <input> : exactly 1, plus --help second
        if len(positionals) == 1:
            return
        elif len(positionals) == 0 and help_flag:
            # Check second usage: only help, no other opts?
            other_opts = {k:v for k,v in opts.items() if k != '--help'}
            if len(other_opts) == 0:
                return
            else:
                raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
        else:
            raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
    elif cmd == 'join':
        # <columns1> <input1> <columns2> <input2> : exactly 4
        if len(positionals) == 4:
            return
        elif len(positionals) == 0 and help_flag:
            other_opts = {k:v for k,v in opts.items() if k != '--help'}
            if len(other_opts) == 0:
                return
            else:
                raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
        else:
            raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
    elif cmd == 'partition':
        # <column> <outdir> [<input>] : 2 or 3
        if len(positionals) in (2,3):
            return
        elif len(positionals) == 0 and help_flag:
            other_opts = {k:v for k,v in opts.items() if k != '--help'}
            if len(other_opts) == 0:
                return
            else:
                raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
        else:
            raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
    elif cmd == 'sample':
        # <sample-size> [<input>] : 1 or 2
        if len(positionals) in (1,2):
            return
        elif len(positionals) == 0 and help_flag:
            other_opts = {k:v for k,v in opts.items() if k != '--help'}
            if len(other_opts) == 0:
                return
            else:
                raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
        else:
            raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
    elif cmd == 'search':
        # <regex> [<input>] : 1 or 2
        if len(positionals) in (1,2):
            return
        elif len(positionals) == 0 and help_flag:
            other_opts = {k:v for k,v in opts.items() if k != '--help'}
            if len(other_opts) == 0:
                return
            else:
                raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
        else:
            raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
    elif cmd == 'select':
        # [--] <selection> [<input>] : 1 or 2 (after handling -- terminator, positionals already stripped of --)
        if len(positionals) in (1,2):
            return
        elif len(positionals) == 0 and help_flag:
            other_opts = {k:v for k,v in opts.items() if k != '--help'}
            if len(other_opts) == 0:
                return
            else:
                raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
        else:
            raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
    elif cmd == 'split':
        # <outdir> [<input>] : 1 or 2
        if len(positionals) in (1,2):
            return
        elif len(positionals) == 0 and help_flag:
            other_opts = {k:v for k,v in opts.items() if k != '--help'}
            if len(other_opts) == 0:
                return
            else:
                raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
        else:
            raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])
    else:
        raise ArgError(b"Invalid arguments.\n\n" + SHORT_USAGES[cmd])

PYEOF
